const DATA=window.SCHEDULE_DATA,E=window.ScheduleEngine,$=id=>document.getElementById(id),DAYS=['周一','周二','周三','周四','周五','周六','周日'];
const LABELS={free:'空闲',course:'有课',other:'其他安排',unknown:'待确认'},COLORS={free:'#00a087',course:'#3c5488',other:'#4dbbd5',unknown:'#d29a43'};
const escapeHTML=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let storeState={contacts:{},rules:{}};try{storeState={...storeState,...JSON.parse(localStorage.getItem('buaa-schedule-2026-settings')||'{}')}}catch{}
let state={view:'query',status:'free',results:[],selectedPerson:DATA.people[0].id,week:6};
let selectedIds=new Set();try{const saved=JSON.parse(localStorage.getItem('buaa-schedule-2026-selection')||'[]');if(Array.isArray(saved))selectedIds=new Set(saved.filter(id=>DATA.people.some(p=>p.id===id&&p.rosterStatus!=='not_in_roster')))}catch{}
let plannerIds=new Set(),plannerResults=[];
const getContact=p=>storeState.contacts[p.id]||p.phone||'';
const saveState=()=>{try{localStorage.setItem('buaa-schedule-2026-settings',JSON.stringify(storeState))}catch{toast('当前浏览器无法保存，请导出设置备份。')}};
function toast(text){$('toast').textContent=text;$('toast').hidden=false;clearTimeout(window.toastTimeout);window.toastTimeout=setTimeout(()=>$('toast').hidden=true,2500)}
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
function weekDate(week,day=1){return E.dateISO(Date.parse(DATA.meta.week1+'T00:00:00Z')+((week-1)*7+day-1)*E.DAY)}
function selectWeek(select){select.innerHTML=Array.from({length:DATA.meta.maxWeek},(_,i)=>`<option value="${i+1}">第 ${i+1} 周 · ${weekDate(i+1).slice(5).replace('-','/')}</option>`).join('');select.value=state.week}
function setView(view){state.view=view;document.querySelectorAll('.view').forEach(n=>n.classList.toggle('active',n.id===view+'View'));document.querySelectorAll('nav button').forEach(n=>n.classList.toggle('active',n.dataset.view===view));if(window.LotteryPanel)window.LotteryPanel.setActive(view==='lottery');const titles={"lottery":["幸运抽奖","志工部与实践部的幸运时刻，开始滚动，点击停止揭晓。"],"query":["时段查询","查看指定时段的课程、空闲人员和联系方式。"],"week":["一周总览","查看每一节的空闲人数，点击格子查看名单。"],"person":["个人课表","按教学周查看课程、地点和备注。"],"directory":["人员名录","查看职务、课表收集情况和联系方式。"],"duty":["值班表","逐次核验有效期内的安排，再分别安排两部门值班。"],"planner":["共同排期","选好同学，查找能一起参加工作的时间。"],"settings":["数据与校历","查看数据来源，设置停课或补课。"]};$('pageTitle').textContent=titles[view][0];$('pageIntro').textContent=titles[view][1];if(view==='week')renderWeek();if(view==='person')renderPerson();if(view==='settings')renderSettings();if(view==='directory')renderDirectory();if(view==='planner')renderPlanner();if(view==='duty')renderDuty()}
function eventsForDisplay(events){const known=events.filter(e=>!e.uncertain),display=events.filter(e=>!e.uncertain||!known.some(k=>k.title===e.title&&k.start===e.start&&k.end===e.end));const map=new Map();for(const e of display){const key=e.title+'|'+e.start+'|'+e.end+'|'+e.uncertain;if(!map.has(key))map.set(key,{...e,rooms:new Set()});if(e.room)map.get(key).rooms.add(e.room)}return [...map.values()].map(e=>({...e,room:[...e.rooms].join(' / ')}))}
function runQuery(){
 const date=$('date').value,start=$('start').value,end=$('end').value;
 const valid=date&&start&&end&&E.min(end)>E.min(start);$('copyFree').disabled=$('exportQuery').disabled=!valid;
 if(!valid){state.results=[];$('summary').innerHTML='';$('results').innerHTML='<div class="empty">请选择有效的日期和时间；结束时间应晚于开始时间。</div>';$('queryLabel').textContent='等待有效查询';$('weekLabel').textContent='';$('statusTabs').innerHTML='';$('queryNotice').innerHTML='';renderSelection();return}
 const info=E.dayInfo(date,DATA,storeState.rules);state.week=Math.max(1,Math.min(DATA.meta.maxWeek,info.week));
 state.results=E.query(DATA,date,start,end,{department:$('department').value,campus:$('campus').value,college:$('college').value,role:$('role').value,search:$('search').value.trim()},storeState.rules);
 $('queryLabel').textContent=date.replaceAll('-','.')+' '+DAYS[info.day-1]+' '+start+' — '+end;
 $('weekLabel').textContent=info.valid?'第 '+info.week+' 周 · '+(info.week%2?'单周':'双周'):'学期范围之外';
 $('queryNotice').innerHTML=info.special?`<div class="notice">此日期已设置：${info.stop?'课程停课':'上第 '+info.courseWeek+' 周'+DAYS[info.courseDay-1]+'的课程'}。原有值班、组会等仍保留。</div>`:((date>='2026-09-25'&&date<='2026-09-27')||(date>='2026-10-01'&&date<='2026-10-07'))?'<div class="notice">此日期处于节假日期间，教学安排需根据学校通知确认。可在“数据与校历”设置停课或补课。</div>':'';
 const counts=Object.fromEntries(Object.keys(LABELS).map(k=>[k,state.results.filter(r=>r.status===k).length]));
 $('summary').innerHTML=Object.entries(LABELS).map(([k,v])=>`<div class="stat" style="--accent:${COLORS[k]}"><div class="stat-title">${v}</div><div class="stat-num">${counts[k]}<small>人</small></div></div>`).join('');
 $('statusTabs').innerHTML=[...Object.keys(LABELS),'all'].map(k=>`<button data-status="${k}" class="${state.status===k?'active':''}">${k==='all'?'全部':LABELS[k]} <span>${k==='all'?state.results.length:counts[k]}</span></button>`).join('');
 document.querySelectorAll('#statusTabs button').forEach(b=>b.onclick=()=>{state.status=b.dataset.status;runQuery()});renderResults();
 document.querySelectorAll('[data-range]').forEach(b=>b.classList.toggle('selected',b.dataset.range===start+','+end));renderSelection();
}
function renderResults(){
 const visible=state.results.filter(r=>state.status==='all'||r.status===state.status).sort((a,b)=>a.person.department.localeCompare(b.person.department,'zh')||a.person.name.localeCompare(b.person.name,'zh'));
 $('results').innerHTML=visible.map(r=>{const p=r.person;return `<article class="person"><div class="person-top"><span class="avatar">${escapeHTML(p.name.slice(-1))}</span><div><button class="person-name" data-person="${p.id}">${escapeHTML(p.name)}</button><div class="muted small">${p.department} · ${escapeHTML(p.role||p.campus)}</div></div><span class="badge ${r.status}">${LABELS[r.status]}</span></div><p class="muted small">${escapeHTML(p.college||'学院尚未提供')}<br>${escapeHTML(p.studentId||'学号尚未提供')} · ${escapeHTML(p.campus)}</p>${r.status==='free'?'<p class="muted small">'+(p.defaultNoClasses?'已按设置默认无课，参加工作请联系本人确认。':'该时段没有课程或其他登记安排。')+'</p>':''}${eventsForDisplay(r.events).map(e=>`<div class="event-line"><strong>${escapeHTML(e.title)}${e.uncertain?' · 周次／时间需确认':''}</strong><span class="muted">${e.endUnknown?e.start+' 开始 · 结束时间待确认':e.start+'–'+e.end}${e.room?' · '+escapeHTML(e.room):''}</span></div>`).join('')}${r.reasons.map(t=>`<div class="event-line" style="border-color:#d6b269;color:#997527">${escapeHTML(t)}</div>`).join('')}<div class="contact">${getContact(p)?escapeHTML(getContact(p)):'<span class="muted">未填写联系方式</span>'}<span class="spacer"></span><button data-contact="${p.id}">编辑</button></div><button class="pick-person" data-pick="${p.id}" aria-pressed="${selectedIds.has(p.id)}">${selectedIds.has(p.id)?'已加入工作名单':'加入工作名单'}</button></article>`}).join('')||'<div class="empty">这个条件下没有对应人员，可切换状态或放宽筛选条件。</div>';
 document.querySelectorAll('[data-person]').forEach(b=>b.onclick=()=>{state.selectedPerson=b.dataset.person;$('personSelect').value=state.selectedPerson;$('personWeek').value=state.week;setView('person')});
 document.querySelectorAll('[data-contact]').forEach(b=>b.onclick=()=>openContact(b.dataset.contact));
}
function download(name,text,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function copyText(text){try{await navigator.clipboard.writeText(text);toast('已复制名单')}catch{const box=document.createElement('textarea');box.value=text;document.body.append(box);box.select();const ok=document.execCommand('copy');box.remove();if(ok)toast('已复制名单');else{download('空闲名单.txt',text);toast('名单已保存为文本文件')}}}
function querySummary(){return $('queryLabel').textContent+'（'+$('weekLabel').textContent+'）'}
$('copyFree').onclick=()=>{const rows=state.results.filter(r=>r.status==='free');const groups=['志工部','实践部'].map(d=>d+'：'+rows.filter(r=>r.person.department===d).map(r=>r.person.name).join('、'));copyText(querySummary()+'\n空闲：'+rows.length+' 人\n'+groups.join('\n')+'\n请联系本人确认能否参与。')};
$('exportQuery').onclick=()=>{const cell=v=>'"'+String(v??'').replaceAll('"','""')+'"';const rows=[['查询日期','开始','结束','教学周','姓名','部门','学号','学院（书院）','职务','校区','状态','课程或已有安排','说明','联系方式'],...state.results.map(r=>[$('date').value,$('start').value,$('end').value,E.dayInfo($('date').value,DATA).week,r.person.name,r.person.department,r.person.studentId||'',r.person.college||'',r.person.role||'',r.person.campus,LABELS[r.status],eventsForDisplay(r.events).map(e=>e.title+' '+e.start+'-'+e.end+' '+e.room).join('；'),r.reasons.join('；'),getContact(r.person)])];download('时段查询_'+$('date').value+'.csv','\uFEFF'+rows.map(r=>r.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8')};
function renderWeek(){
 state.week=Number($('weekSelect').value)||state.week;$('prevWeek').disabled=state.week===1;$('nextWeek').disabled=state.week===DATA.meta.maxWeek;$('weekRange').textContent=weekDate(state.week)+' — '+weekDate(state.week,7)+' · '+(state.week%2?'单周':'双周');
 const filter={department:$('weekDept').value,campus:$('weekCampus').value};const total=DATA.people.filter(p=>p.rosterStatus!=='not_in_roster'&&(!filter.department||p.department===filter.department)&&(!filter.campus||p.campus===filter.campus)).length;
 let html='<table class="week-grid"><thead><tr><th>节次 / 时间</th>'+DAYS.map((d,i)=>'<th>'+d+'<br><span class="small">'+weekDate(state.week,i+1).slice(5).replace('-','/')+'</span></th>').join('')+'</tr></thead><tbody>';
 for(const slot of DATA.slots){html+='<tr><td class="time-col"><strong>第 '+slot.period+' 节</strong><br>'+slot.start+'–'+slot.end+'</td>';for(let day=1;day<=7;day++){const result=E.query(DATA,weekDate(state.week,day),slot.start,slot.end,filter,storeState.rules),free=result.filter(r=>r.status==='free').length,unknown=result.filter(r=>r.status==='unknown').length;html+=`<td><button class="heat" data-heat="${day},${slot.period}" style="--heat:hsl(174 37% ${13+22*free/Math.max(total,1)}%)" aria-label="${DAYS[day-1]}第${slot.period}节，${free}人空闲"><strong>${free}<span style="display:inline;font-size:14px"> 人</span></strong><span>${unknown} 人需确认</span></button></td>`}html+='</tr>'}
 $('heatmap').innerHTML=html+'</tbody></table>';document.querySelectorAll('[data-heat]').forEach(b=>b.onclick=()=>{const [day,period]=b.dataset.heat.split(',').map(Number),s=DATA.slots[period-1];openTime(weekDate(state.week,day),s.start,s.end,filter)});
 let ranked=[];for(let day=1;day<=7;day++){for(let hour=8;hour<=20;hour++){const a=String(hour).padStart(2,'0')+':00',b=String(hour+2).padStart(2,'0')+':00';const rs=E.query(DATA,weekDate(state.week,day),a,b,filter,storeState.rules);ranked.push({day,start:a,end:b,count:rs.filter(r=>r.status==='free').length})}}
 ranked.sort((a,b)=>b.count-a.count||a.day-b.day||a.start.localeCompare(b.start));$('ranking').innerHTML=ranked.slice(0,6).map(r=>`<button class="rank-item" data-rank="${r.day},${r.start},${r.end}"><strong>${r.count}</strong>人空闲<br><span class="muted small">${DAYS[r.day-1]} · ${weekDate(state.week,r.day).slice(5)} · ${r.start}–${r.end}</span></button>`).join('');document.querySelectorAll('[data-rank]').forEach(b=>b.onclick=()=>{const [day,start,end]=b.dataset.rank.split(',');openTime(weekDate(state.week,Number(day)),start,end,filter)});
}
function openTime(date,start,end,filter={}){$('date').value=date;$('start').value=start;$('end').value=end;$('department').value=filter.department||'';$('campus').value=filter.campus||'';$('search').value='';$('college').value='';$('role').value='';state.status='free';setView('query');runQuery();window.scrollTo(0,0)}
function renderPerson(){
 const p=DATA.people.find(p=>p.id===$('personSelect').value)||DATA.people[0];state.selectedPerson=p.id;const week=Number($('personWeek').value)||state.week;
 $('sourceLink').href=p.sourceUrl||p.rosterSourceUrl||DATA.meta.rosterSourceUrl;$('sourceLink').textContent=p.hasTimetable===false?'查看任职名单 ↗':'查看当前采用的课表 ↗';
 $('personMeta').innerHTML='<strong style="font-size:23px">'+escapeHTML(p.name)+'</strong> <span class="muted">'+p.department+' · '+p.campus+' · 第 '+week+' 周</span><p class="muted small" style="margin-top:9px">'+escapeHTML(p.studentId||'学号尚未提供')+' · '+escapeHTML(p.college||'学院尚未提供')+' · '+escapeHTML(p.role||'职务尚未提供')+'<br>联系方式：'+escapeHTML(getContact(p)||'尚未提供')+'</p>'+(p.defaultNoClasses?'<div class="notice">'+escapeHTML(p.defaultNoClassesNote)+'</div>':p.hasTimetable===false?'<div class="notice">尚未收集到此人的课表，下面的空白不代表无课。</div>':'')+(p.semesterAssumed?'<div class="notice">原表标题为第 '+p.sourceWeek+' 周，现作为整学期课表使用；课程内明确的周次和单双周仍按标注执行。</div>':'')+(p.rosterNotes?'<p class="muted small">任职备注：'+escapeHTML(p.rosterNotes)+'</p>':'')+((p.timetableSources||[]).length>1?'<p class="small" style="margin-top:10px">课表版本：'+p.timetableSources.map(s=>'<a href="'+s.url+'" target="_blank" rel="noopener">'+(s.selected?'当前采用':'历史版本')+(s.week?' · 原第 '+s.week+' 周':' · 原学期表')+'</a>').join('　')+'</p>':'');
 let html='<table class="week-grid"><thead><tr><th>节次 / 时间</th>'+DAYS.map((d,i)=>'<th>'+d+'<br>'+weekDate(week,i+1).slice(5)+'</th>').join('')+'</tr></thead><tbody>';
 for(const s of DATA.slots){html+='<tr><td class="time-col"><strong>第 '+s.period+' 节</strong><br>'+s.start+'–'+s.end+'</td>';for(let day=1;day<=7;day++){const r=E.evaluate(p,weekDate(week,day),s.start,s.end,DATA,storeState.rules);html+='<td>'+eventsForDisplay(r.events).map(e=>`<div class="course-cell ${e.kind==='other'?'other':''} ${e.uncertain?'uncertain':''}"><strong>${escapeHTML(e.title)}</strong><br><span class="small">${escapeHTML(e.room||'地点未注明')}</span>${e.uncertain?'<br><span class="small">周次／时间需确认</span>':''}</div>`).join('')+(!r.events.length?'<span class="cell-free">'+(r.status==='free'?'空闲':'需确认')+'</span>':'')+'</td>'}html+='</tr>'}
 $('personalGrid').innerHTML=html+'</tbody></table>';$('personNotes').innerHTML=[...new Set(p.notes)].map(n=>'<li>'+escapeHTML(n)+'</li>').join('')||'<li>原表没有额外备注。</li>';
}
function openContact(id){state.contactPerson=id;$('contactName').textContent=DATA.people.find(p=>p.id===id).name+' · 可填写手机号、微信号或备注';$('contactValue').value=getContact(DATA.people.find(p=>p.id===id));$('contactDialog').showModal()}
$('contactCancel').onclick=()=>$('contactDialog').close();$('contactSave').onclick=()=>{storeState.contacts[state.contactPerson]=$('contactValue').value.trim();saveState();$('contactDialog').close();runQuery();if(state.view==='person')renderPerson();if(state.view==='directory')renderDirectory();toast('联系方式已保存')};$('editContact').onclick=()=>openContact(state.selectedPerson);
function renderSettings(){
 const stats=DATA.meta.departmentStats;
 $('dataQuality').innerHTML='<div class="row" style="margin:20px 0"><strong style="font-size:32px">'+DATA.meta.activePeopleCount+'</strong><span class="muted">位现任同学 · 志工部 '+DATA.meta.volunteerCount+' / 实践部 '+DATA.meta.practiceCount+'</span></div><table><thead><tr><th>部门</th><th>任职人数</th><th>已收课表</th><th>默认无课</th><th>待补课表</th></tr></thead><tbody>'+Object.entries(stats).map(([dept,x])=>'<tr><td>'+dept+'</td><td>'+x.total+'</td><td>'+x.withTimetable+'</td><td>'+(x.defaultNoClasses||0)+'</td><td>'+x.missing.length+'</td></tr>').join('')+'</tbody></table><p class="muted small" style="margin-top:15px">原始课表 '+DATA.meta.sourceCount+' 份；同一人有多份课表时，采用最新一份作为整学期课表。'+(DATA.meta.unmatchedTimetables.length?DATA.meta.unmatchedTimetables.map(escapeHTML).join('、')+' 的课表归属待核对，默认不计入现任人员查询。':'')+'</p><div class="notice">统一口径：单周标题课表均按整学期使用，课程内明确的周次与单双周保留。“部员”与“学生干部”统一显示为“学生干部”。</div>';
 $('rulesList').innerHTML=Object.entries(storeState.rules).sort().map(([date,r])=>`<div class="row" style="margin-bottom:8px"><span class="small">${escapeHTML(date)} · ${r.mode==='stop'?'课程停课':'上第 '+Number(r.week)+' 周'+DAYS[Number(r.day)-1]+'课程'}</span><button data-delete-rule="${escapeHTML(date)}" style="font-size:14px;padding:4px 8px">移除</button></div>`).join('')||'<p class="muted small">尚未添加特殊日期设置。</p>';document.querySelectorAll('[data-delete-rule]').forEach(b=>b.onclick=()=>{delete storeState.rules[b.dataset.deleteRule];saveState();invalidatePlanner();invalidateDuty();renderSettings();runQuery()});
 $('sources').innerHTML='<div class="notice">未收集课表：'+Object.entries(DATA.meta.departmentStats).map(([dept,x])=>dept+'：'+x.missing.map(escapeHTML).join('、')).join('；')+'。默认无课：'+DATA.meta.defaultNoClasses.map(escapeHTML).join('、')+(DATA.meta.unmatchedTimetables.length?'。课表归属待核对：'+DATA.meta.unmatchedTimetables.map(escapeHTML).join('、'):'')+'。</div>'+DATA.people.map(p=>'<div class="source-row"><strong>'+escapeHTML(p.name)+'</strong><span class="muted">'+p.department+'</span><span class="muted small">'+escapeHTML(p.campus)+(p.semesterAssumed?' · 按学期使用':'')+'</span><span>'+((p.timetableSources||[]).length?p.timetableSources.map(s=>'<a href="'+s.url+'" target="_blank" rel="noopener">'+(s.selected?'当前采用':'历史版本')+' ↗</a>').join('　'):'<a href="'+(p.rosterSourceUrl||DATA.meta.rosterSourceUrl)+'" target="_blank" rel="noopener">任职名单 ↗</a>')+'</span></div>').join('');

}
$('saveRule').onclick=()=>{const date=$('ruleDate').value;if(!date){toast('请先选择日期');return}storeState.rules[date]={mode:$('ruleMode').value,week:Number($('ruleWeek').value),day:Number($('ruleDay').value)};saveState();invalidatePlanner();invalidateDuty();renderSettings();runQuery();toast('日期设置已保存')};
$('exportBackup').onclick=()=>download('北航课表查询_设置备份.json',JSON.stringify({type:'buaa-schedule-2026-settings',version:1,...storeState},null,2),'application/json');$('importBackup').onclick=()=>$('backupFile').click();
$('backupFile').onchange=async ev=>{try{const file=ev.target.files[0];if(!file)return;const d=JSON.parse(await file.text());if(d.type!=='buaa-schedule-2026-settings'||!d.contacts||!d.rules)throw Error();const safeContacts=Object.fromEntries(Object.entries(d.contacts).filter(([k,v])=>DATA.people.some(p=>p.id===k)&&typeof v==='string'));const safeRules={};for(const [k,r] of Object.entries(d.rules)){if(/^\d{4}-\d{2}-\d{2}$/.test(k)&&['stop','replace'].includes(r.mode)&&Number(r.week)>=1&&Number(r.week)<=DATA.meta.maxWeek&&Number(r.day)>=1&&Number(r.day)<=7)safeRules[k]={mode:r.mode,week:Number(r.week),day:Number(r.day)}}storeState={contacts:{...storeState.contacts,...safeContacts},rules:{...storeState.rules,...safeRules}};saveState();invalidatePlanner();invalidateDuty();renderSettings();runQuery();toast('设置备份已导入')}catch{toast('这不是有效的课表查询设置备份')}ev.target.value=''};
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{if(b.dataset.view==='week')$('weekSelect').value=state.week;if(b.dataset.view==='person')$('personWeek').value=state.week;setView(b.dataset.view)});
