function setupGlass(){
 if(document.body.dataset.platformTheme==='night')return;
 // Approximate curved edge refraction. The separate layer leaves all text untouched.
 if(!/Chrome|Chromium|Edg/.test(navigator.userAgent)||!window.ResizeObserver||matchMedia('(prefers-reduced-motion: reduce)').matches||matchMedia('(prefers-reduced-transparency: reduce)').matches)return;
 const aside=document.querySelector('aside'),surface=document.createElement('div');surface.className='lens-surface';surface.setAttribute('aria-hidden','true');aside.prepend(surface);
 let pending;new ResizeObserver(()=>{clearTimeout(pending);pending=setTimeout(()=>{
  const w=Math.round(aside.offsetWidth),h=Math.round(aside.offsetHeight);if(!w||!h)return;const scale=Math.min(1,900/Math.max(w,h)),cw=Math.round(w*scale),ch=Math.round(h*scale),c=document.createElement('canvas');c.width=cw;c.height=ch;const ctx=c.getContext('2d'),im=ctx.createImageData(cw,ch),radius=parseFloat(getComputedStyle(aside).borderRadius)*scale,edge=13*scale;
  for(let y=0;y<ch;y++)for(let x=0;x<cw;x++){const cx=Math.max(radius,Math.min(cw-radius,x)),cy=Math.max(radius,Math.min(ch-radius,y)),dx=x-cx,dy=y-cy,dist=Math.hypot(dx,dy),d=dist>0?radius-dist:Math.min(x,cw-1-x,y,ch-1-y),amount=d>=0&&d<edge?Math.sin(Math.PI*d/edge)*.9:0;let nx=0,ny=0;if(dist>0){nx=dx/dist;ny=dy/dist}else{const ds=[x,cw-1-x,y,ch-1-y],k=ds.indexOf(Math.min(...ds));nx=k===0?-1:k===1?1:0;ny=k===2?-1:k===3?1:0}const i=(y*cw+x)*4;im.data[i]=128+Math.round(nx*amount*110);im.data[i+1]=128+Math.round(ny*amount*110);im.data[i+2]=128;im.data[i+3]=255}ctx.putImageData(im,0,0);
  let svg=$('glassFilters');if(!svg){svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.id='glassFilters';svg.setAttribute('width','0');svg.setAttribute('height','0');svg.setAttribute('aria-hidden','true');svg.style.position='fixed';document.body.append(svg)}svg.innerHTML=`<defs><filter id="navLens" x="0" y="0" width="1" height="1" color-interpolation-filters="sRGB"><feImage href="${c.toDataURL()}" x="0" y="0" width="${w}" height="${h}" preserveAspectRatio="none" result="map"/><feDisplacementMap in="SourceGraphic" in2="map" scale="14" xChannelSelector="R" yChannelSelector="G"/></filter></defs>`;surface.style.backdropFilter='url(#navLens) blur(2px) saturate(135%)';
 },150)}).observe(aside);
 let tick=false;document.addEventListener('pointermove',ev=>{if(tick||ev.pointerType==='touch'||document.body.classList.contains('clear-mode'))return;const el=ev.target.closest('aside,.card,.stat');if(!el)return;tick=true;requestAnimationFrame(()=>{const r=el.getBoundingClientRect();el.style.setProperty('--glass-x',Math.round((ev.clientX-r.left)/r.width*100)+'%');el.style.setProperty('--glass-y',Math.round((ev.clientY-r.top)/r.height*100)+'%');tick=false})},{passive:true});
}
