const DUTY=window.DutyScheduler;let dutyOptions={overrides:{}};try{const saved=JSON.parse(localStorage.getItem('buaa-duty-2026-options')||'{}');dutyOptions.overrides=sanitizeDutyOverrides(saved.overrides||{})}catch{}
let dutyPlan=null,dutySeed=0;
function sanitizeDutyOverrides(raw){const safe={};for(const [id,o] of Object.entries(raw||{})){if(!DATA.people.some(p=>p.id===id)||!o||typeof o!=='object')continue;const item={};if(['学院路','沙河','待确认'].includes(o.campus))item.campus=o.campus;if(['g1','g2','g3','g4','grad','unknown'].includes(o.grade))item.grade=o.grade;if(o.exclude===true)item.exclude=true;if(Object.keys(item).length)safe[id]=item}return safe}
function saveDutyOptions(){try{localStorage.setItem('buaa-duty-2026-options',JSON.stringify(dutyOptions))}catch{toast('当前浏览器无法保存，请导出核对备份')}}
function invalidateDuty(){dutyPlan=null;if($('dutyOutput'))$('dutyOutput').innerHTML='';if($('dutyPending'))$('dutyPending').hidden=false}
function dutySlotLabel(slot){return DAYS[slot.day-1]+' '+slot.label}
function dutyPeopleMap(){return new Map(DATA.people.map(p=>[p.id,p]))}
function dutyRangeText(){return dutyPlan.start+' 至 '+dutyPlan.end}
function dutyStatusText(p){return p.formal?'按已登记安排核验通过':(p.complete?'草案条件满足，资料仍待核对':'值班草案，尚有缺口')}
function renderDuty(){
 const info=DATA.meta.pendingTimetableRefresh;$('dutyDataStatus').textContent=info?'新课表尚未读取：当前课程资料仍为 '+(DATA.meta.timetableUpdated||'2026-10-14')+'。本次人员调整已生效；以下只能生成基于现有资料的草案。':'当前资料更新于 '+(DATA.meta.timetableUpdated||DATA.meta.updated)+'。请核对课程和校区后使用排班结果。';renderDutyRoster();if(!dutyPlan)computeDuty(false);
 const recommended=DATA.people.filter(p=>p.timetableVerification==='recommended_unconfirmed');if(recommended.length)$('dutyDataStatus').textContent+=' '+recommended.map(p=>p.name).join('、')+'上传的是推荐课表，个人实际选课尚未确认，暂不能据此认定可值班。';
}
function computeDuty(variant=false){
 invalidateDuty();try{if($('dutyStart').value<'2026-10-17'||$('dutyEnd').value>DUTY.endDates(DATA).duty)throw Error('请在本次生效日期与本学期范围内选择');if(variant)dutySeed++;dutyPlan=DUTY.generateBest(DATA,{campus:$('dutyCampus').value,start:$('dutyStart').value,end:$('dutyEnd').value,overrides:dutyOptions.overrides,seed:dutySeed},storeState.rules);if(!dutyPlan.audit.valid){const reason=dutyPlan.audit.errors.join('；');dutyPlan=null;throw Error('方案作废：'+reason)}$('dutyPending').hidden=true;renderDutyOutput()}catch(e){toast(e.message||'无法计算排班，请检查日期')}
}
function dutyIssues(p){
 const warnings=[];const ends=DUTY.endDates(DATA);if(p.pending)warnings.push(['新课表未核验','当前使用 '+(DATA.meta.timetableUpdated||'2026-10-14')+' 课程资料，不能据此确认 10 月 17 日后更新文件的课程。']);if(p.end<ends.duty)warnings.push(['仅覆盖部分值班期','当前表截至 '+p.end+'；本学期值班截至 '+ends.duty+'，第18–19周不值班。']);for(const dept of DUTY.DEPTS){const c=p.counts[dept];if(c.arithmeticShortfall)warnings.push([dept+' 的人数不足',c.people+' 人 × 每人最多 2 班 = '+c.capacity+' 人次，少于覆盖 20 格所需的 20 人次，至少缺 '+c.arithmeticShortfall+' 格。'])}
 if(p.campus==='学院路'&&p.counts['实践部'].capacity<30)warnings.push(['双人配置无法接近对半','实践部当前最多可提供 '+p.counts['实践部'].capacity+' 人次；若 1+2 与 2+1 各 10 格，需要每部门各 30 人次。没有通过加班次或启用大四、研究生填补。']);
 if(p.gaps.length)warnings.push(['仍缺 '+p.gaps.length+' 个部门值班名额',p.gaps.map(g=>dutySlotLabel(p.slots[g.slot])+' '+g.department).join('；')]);if(p.shortage.length)warnings.push(['个人班次数未达到目标',p.shortage.map(w=>w.name+'：'+w.assigned.length+'/'+w.min+' 班').join('；')]);if(p.preferences.length)warnings.push(['仍有安排偏好未满足',p.preferences.map(w=>{const ss=w.assigned.map(i=>p.slots[i]),reasons=[];if(ss.length===2&&ss[0].day===ss[1].day)reasons.push('同一天');if(ss.length===2&&ss[0].day===ss[1].day&&Math.abs(ss[0].block-ss[1].block)===1)reasons.push('相邻时段');if(ss.length===2&&ss.every(s=>s.block===0))reasons.push('两次早班');return w.name+'：'+reasons.join('、')}).join('；')]);if(!p.audit.valid)warnings.push(['校验未通过',p.audit.errors.join('；')]);return warnings;
}
