 html+='<div class="card"><h2>每人班次数与未排原因</h2><p class="muted small" style="margin:10px 0 18px">学院路大三可排 1–2 班，其他纳入人员目标 2 班；沙河所有纳入人员目标 2 班。年级为按学号推定的结果，可在下方核对。</p><div class="table-scroll"><table class="duty-workload"><thead><tr>'+['姓名 / 部门','年级','目标 / 已排','班次','说明'].map(t=>'<th>'+t+'</th>').join('')+'</tr></thead><tbody>'+p.workloads.map(w=>'<tr class="'+(!w.excluded&&w.assigned.length<w.min?'duty-shortage':'')+'"><td><strong>'+escapeHTML(w.name)+'</strong><br>'+escapeHTML(w.department)+'</td><td>'+w.grade+'<br><span class="small muted">'+w.gradeBasis+'</span></td><td>'+ (w.min===w.max?w.min:w.min+'–'+w.max)+' / <strong>'+w.assigned.length+'</strong></td><td>'+w.assigned.map(i=>dutySlotLabel(p.slots[i])).join('<br>')+'</td><td>'+escapeHTML(w.excluded||(!w.availableCount?'有效期内没有可确认的固定空闲时段':w.preferencePenalty?'有早班／同日等偏好未满足':'已核对可用时段'))+'</td></tr>').join('')+'</tbody></table></div></div>';
 $('dutyOutput').innerHTML=html;renderDutyDisplayMarkers();$('dutyRecalculate').onclick=()=>computeDuty(true);$('dutyExport').onclick=exportDuty;$('dutyExcel').onclick=exportDutyExcel;$('dutyCopy').onclick=()=>copyText(dutyReport(dutyPlan));$('dutyPrint').onclick=()=>window.print();document.querySelectorAll('[data-duty-slot]').forEach(b=>b.onclick=()=>showDutyCandidates(Number(b.dataset.dutySlot),b.dataset.dutyDept));
