function dutyReport(p){const map=dutyPeopleMap();return p.campus+'每周值班草案\n有效期：'+p.start+' 至 '+p.end+'\n课程资料：'+(DATA.meta.timetableUpdated||DATA.meta.updated)+(p.pending?'（新课表尚未核验）':'')+'\n'+p.slots.map(s=>dutySlotLabel(s)+'｜'+DUTY.DEPTS.map(d=>d+'：'+(p.grid[s.index].departments[d].map(id=>map.get(id).name).join('、')||'待补')).join('；')).join('\n')+'\n\n'+dutyIssues(p).map(([a,b])=>a+'：'+b).join('\n')}
function exportDuty(){if(!dutyPlan)return;const esc=v=>'"'+String(v??'').replaceAll('"','""')+'"',rows=[['状态','校区','方式','有效期开始','有效期结束','星期','节次','开始','结束','部门','人员','本部门人数','两部门合计','课程资料日期','提示']];for(const campus of ['学院路','沙河']){const p=campus===dutyPlan.campus?dutyPlan:DUTY.generateBest(DATA,{campus,start:dutyPlan.start,end:dutyPlan.end,overrides:dutyOptions.overrides,seed:dutySeed},storeState.rules),map=dutyPeopleMap();for(const s of p.grid)for(const dept of DUTY.DEPTS){const ids=s.departments[dept];rows.push(['草案',campus,campus==='沙河'?'线上':'线下',p.start,p.end,DAYS[s.day-1],s.label,s.start,s.end,dept,ids.map(id=>map.get(id).name).join('、')||'待补',ids.length,DUTY.DEPTS.reduce((n,d)=>n+s.departments[d].length,0),DATA.meta.timetableUpdated||DATA.meta.updated,p.pending?'新课表尚未核验；不是整学期正式确认表':'以已登记课表与学校通知为准'])}}download('两校区值班草案_'+dutyPlan.start+'.csv','\uFEFF'+rows.map(r=>r.map(esc).join(',')).join('\r\n'),'text/csv;charset=utf-8')}
