function renderDutyRoster(){const ps=DUTY.profiles(DATA,dutyOptions.overrides);$('dutyUnknownCampus').textContent='校区待确认（不自动加入任何校区）：'+(ps.filter(p=>p.campus==='待确认').map(p=>p.person.name).join('、')||'无');$('dutyRoster').innerHTML='<table class="duty-roster"><thead><tr><th>姓名 / 部门</th><th>资料校区</th><th>核对校区</th><th>资料年级</th><th>核对年级</th><th>本次不参与</th></tr></thead><tbody>'+ps.map(q=>{const p=q.person,o=dutyOptions.overrides[p.id]||{},base=DUTY.gradeOf(p);return '<tr><td><strong>'+escapeHTML(p.name)+'</strong><br>'+p.department+'</td><td>'+escapeHTML(p.campus)+'<br><span class="muted small">'+escapeHTML(p.campusBasis||'资料未注明')+'</span></td><td><select data-duty-campus="'+p.id+'"><option value="">按资料</option>'+['学院路','沙河','待确认'].map(x=>'<option '+(o.campus===x?'selected':'')+'>'+x+'</option>').join('')+'</select></td><td>'+base.label+'<br><span class="muted small">'+base.basis+'</span></td><td><select data-duty-grade="'+p.id+'"><option value="">按学号推定</option>'+Object.entries({g1:'大一',g2:'大二',g3:'大三',g4:'大四及以上',grad:'研究生',unknown:'待确认'}).map(([v,t])=>'<option value="'+v+'" '+(o.grade===v?'selected':'')+'>'+t+'</option>').join('')+'</select></td><td><input type="checkbox" aria-label="'+escapeHTML(p.name)+'不参与排班" data-duty-exclude="'+p.id+'" '+(o.exclude?'checked':'')+'></td></tr>'}).join('')+'</tbody></table>';function change(id,key,value){dutyOptions.overrides[id]??={};if(value)dutyOptions.overrides[id][key]=value;else delete dutyOptions.overrides[id][key];dutyOptions.overrides=sanitizeDutyOverrides(dutyOptions.overrides);saveDutyOptions();invalidateDuty();renderDutyRoster()}document.querySelectorAll('[data-duty-campus]').forEach(n=>n.onchange=()=>change(n.dataset.dutyCampus,'campus',n.value));document.querySelectorAll('[data-duty-grade]').forEach(n=>n.onchange=()=>change(n.dataset.dutyGrade,'grade',n.value));document.querySelectorAll('[data-duty-exclude]').forEach(n=>n.onchange=()=>change(n.dataset.dutyExclude,'exclude',n.checked));}
$('dutyGenerate').onclick=()=>computeDuty(false);$('dutyCampus').onchange=()=>{invalidateDuty();computeDuty(false)};['dutyStart','dutyEnd'].forEach(id=>$(id).onchange=invalidateDuty);$('dutyFullTerm').onclick=()=>{$('dutyEnd').value=DUTY.endDates(DATA).duty;computeDuty(false)};$('dutyTeaching').onclick=()=>{$('dutyEnd').value=DUTY.endDates(DATA).teaching;computeDuty(false)};$('dutyDialogClose').onclick=()=>$('dutyDialog').close();$('dutyResetOptions').onclick=()=>{dutyOptions={overrides:{}};saveDutyOptions();invalidateDuty();renderDutyRoster()};$('dutyExportOptions').onclick=()=>download('值班校区年级核对备份.json',JSON.stringify({type:'buaa-duty-2026-options',overrides:dutyOptions.overrides},null,2),'application/json');$('dutyImportOptions').onclick=()=>$('dutyOptionsFile').click();$('dutyOptionsFile').onchange=async ev=>{try{const file=ev.target.files[0];if(!file)return;const d=JSON.parse(await file.text());if(d.type!=='buaa-duty-2026-options'||!d.overrides)throw Error();dutyOptions.overrides=sanitizeDutyOverrides(d.overrides);saveDutyOptions();invalidateDuty();renderDutyRoster();toast('核对备份已导入，请重新计算')}catch{toast('这不是有效的值班核对备份')}ev.target.value=''};

function exportDutyExcel(){
 if(!dutyPlan){toast('请先计算值班表');return}
 try{
  const plans=['学院路','沙河'].map(campus=>campus===dutyPlan.campus?dutyPlan:DUTY.generateBest(DATA,{campus,start:dutyPlan.start,end:dutyPlan.end,overrides:dutyOptions.overrides,seed:dutySeed},storeState.rules));
  for(const plan of plans){const audit=DUTY.verify(DATA,plan,dutyOptions.overrides,storeState.rules);if(!audit.valid)throw Error('方案作废：'+audit.errors.join('；'))}
  const result=window.DutyWorkbook.build(DATA,plans,getContact);
  download('2026秋季值班表_'+dutyPlan.start+'.xlsx',result.bytes,'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
  toast('已按26秋示例导出两个工作表；大四展示人员无需到岗，不计实际值班');
 }catch(e){toast(e.message||'Excel 导出失败，请重新计算')}
}
function renderDutyDisplayMarkers(){
 if(!dutyPlan||dutyPlan.campus!=='学院路')return;
 const list=DUTY.profiles(DATA,dutyOptions.overrides).filter(q=>q.person.dutyDisplayOnly&&q.person.role!=='部长'&&q.campus==='学院路'&&q.grade.key==='g4'&&!q.excluded);
 for(const q of list){const p=q.person,button=document.querySelector('[data-duty-slot="'+p.dutyDisplayOnly.slot+'"][data-duty-dept="'+p.department+'"]');if(!button)continue;const cell=button.closest('td'),badge=document.createElement('span');badge.className='duty-person duty-display-only';badge.textContent=p.name+'（仅展示）';badge.title='无需到岗，不计实际班次、人数或覆盖';badge.style.cssText='border:1px dashed #8798ad;background:rgba(135,152,173,.10);color:var(--muted)';cell.insertBefore(badge,cell.querySelector('.duty-cell-note'))}
 const metadata=document.querySelector('#dutyOutput .duty-metadata');if(metadata){const note=document.createElement('span');note.style.display='block';note.textContent='大四仅展示：'+list.map(q=>q.person.name).join('、')+'。无需到岗，不计实际值班和缺口覆盖；部长不进入值班格。';metadata.append(note)}
}


/* BUAA_LOTTERY_PLATFORM_INTEGRATION */
(() => {
 'use strict';
 const frame=document.getElementById('lotteryFrame'),shell=document.getElementById('lotteryShell');
 const loading=document.getElementById('lotteryLoading'),button=document.getElementById('lotteryFullscreen');
 const targetOrigin=location.protocol==='file:'?'*':location.origin;
 let active=false,loaded=false;
 function viewport(){
  if(!loaded||!active)return;
  const rect=frame.getBoundingClientRect(),aside=document.querySelector('body>aside');
  const stickyBottom=aside&&getComputedStyle(aside).position==='sticky'?Math.max(0,aside.getBoundingClientRect().bottom+8):0;
  const visibleTop=Math.max(0,rect.top,stickyBottom),visibleBottom=Math.min(innerHeight,rect.bottom);
  frame.contentWindow.postMessage({type:'buaa-lottery-viewport',top:Math.max(0,visibleTop-rect.top),height:Math.max(120,visibleBottom-visibleTop)},targetOrigin);
 }
 function notify(){if(loaded){frame.contentWindow.postMessage({type:'buaa-lottery-visibility',active},targetOrigin);viewport();}}
 window.LotteryPanel={setActive(value){
  active=Boolean(value);
  if(active&&!frame.hasAttribute('src'))frame.src='lottery.html?v=20261024-64';
  if(active&&location.hash!=='#lottery')history.replaceState(null,'','#lottery');
  else if(!active&&location.hash==='#lottery')history.replaceState(null,'',location.pathname+location.search);
  requestAnimationFrame(notify);
 }};
 frame.addEventListener('load',()=>{if(!frame.hasAttribute('src'))return;loaded=true;loading.hidden=true;notify();});
 window.addEventListener('message',event=>{
  if(event.source!==frame.contentWindow||(location.protocol!=='file:'&&event.origin!==location.origin))return;
  if(event.data?.type==='buaa-lottery-height'&&Number.isFinite(event.data.height)&&event.data.height>=100&&event.data.height<=10000)frame.style.height=Math.ceil(event.data.height)+'px';
  if(event.data?.type==='buaa-lottery-modal')viewport();
 });
 window.addEventListener('resize',viewport);
 window.addEventListener('scroll',viewport,{passive:true});
 document.addEventListener('fullscreenchange',()=>requestAnimationFrame(viewport));
 button.addEventListener('click',async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else if(shell.requestFullscreen)await shell.requestFullscreen();else toast('当前浏览器不支持全屏，可使用浏览器的全屏模式。');}catch{toast('未能进入全屏，请使用浏览器的全屏模式。');}});
 window.addEventListener('hashchange',()=>{if(location.hash==='#lottery')setView('lottery');});
 if(location.hash==='#lottery')setView('lottery');
})();

